typedef struct { _Atomic size_t refs; size_t len; char *data; } CowBuf;

static void cow_write(CowBuf **p) {          /* detach before writing */
    CowBuf *b = *p;
    if (atomic_load(&b->refs) > 1) {
        CowBuf *n = cow_new(b->len);
        memcpy(n->data, b->data, b->len);
        cow_release(b);                      /* no owner left behind */
        *p = n;
    }
}
